async function openArtist(page,name,more=false){if(!page){view('search');$('query').value=name;searchKind='tracks';$('searchTracks').classList.add('selected');$('searchArtists').classList.remove('selected');return doSearch();}const generation=++artistGeneration;if(!more){artistProfile={page,name};$('favoriteArtist').textContent=state.favoriteArtists.some(a=>a.page===page)?'★ Любимый исполнитель':'☆ В любимые исполнители';artistTracks=[];artistOffset=0;$('artistName').textContent=name;$('artistCaption').textContent='Профиль SoundCloud · загружаем треки…';$('artistTracks').replaceChildren();view('artist');}$('moreArtist').disabled=true;try{const data=await provider.artist(page,artistOffset);if(generation!==artistGeneration)return;artistTracks=unique([...artistTracks,...data.tracks]);artistOffset+=30;artistProfile.name=data.name;$('artistName').textContent=data.name;$('artistCaption').textContent='Треки этого профиля · загружено '+artistTracks.length;list('artistTracks',artistTracks);$('moreArtist').hidden=data.tracks.length===0;if(activeAccount)provider.prefetch(artistTracks.slice(0,2));}catch(e){$('artistCaption').textContent='Не удалось открыть профиль: '+e.message;}finally{$('moreArtist').disabled=false;}}
