async function doSearch(more=false){const searchStarted=performance.now();if(!more){searchController?.abort();searchGeneration++;query=$('query').value.trim();searchOffset=0;results=[];artistResults=[];}if(!query)return;const gen=searchGeneration;searchController=new AbortController();$('searchStatus').textContent=searchKind==='artists'?'Ищем исполнителей…':'Ищем доступные записи…';$('moreSearch').hidden=true;try{const kind=searchKind,found=kind==='artists'?await provider.api('catalogue_artists',query,searchOffset):await provider.search(query,searchOffset,searchController.signal);if(gen!==searchGeneration)return;if(kind==='artists')artistResults=[...new Map([...artistResults,...found].map(a=>[a.name.toLowerCase(),a])).values()];else results=unique([...results,...found]);searchOffset+=30;renderSearch();const count=kind==='artists'?artistResults.length:results.length;$('searchStatus').textContent=count?'Найдено: '+count:'Не нашли совпадений. Попробуй название трека или другую версию.';$('moreSearch').hidden=kind==='artists'||found.length===0;qualityEvent('search',{duration:performance.now()-searchStarted,count:found.length});}catch(e){if(gen!==searchGeneration||e.name==='AbortError')return;qualityEvent('search',{duration:performance.now()-searchStarted,ok:false});$('searchStatus').textContent='Поиск недоступен: '+e.message+'. Попробуй ещё раз.';}}
