function renderFavoriteArtists(){provider.setArtistHints(state.favoriteArtists);const root=$('favoriteArtists');root.replaceChildren();$('profileCaption').textContent=state.profile.name?'ПРОФИЛЬ · '+state.profile.name:'ТВОЙ ВКУС';for(const a of state.favoriteArtists){const tile=document.createElement('div');tile.className='favorite-artist';const b=document.createElement('button');b.className='favorite-open';const avatar=document.createElement('span');avatar.className='artist-avatar';avatar.textContent=a.name.slice(0,2).toUpperCase();const name=document.createElement('strong');name.textContent=a.name;b.append(avatar,name);b.onclick=()=>{if(a.page)openArtist(a.page,a.name);else{view('search');$('query').value=a.name;searchKind='tracks';$('searchTracks').classList.add('selected');$('searchArtists').classList.remove('selected');$('searchForm').requestSubmit();}};const remove=document.createElement('button');remove.className='favorite-remove';remove.textContent='×';remove.setAttribute('aria-label','Убрать '+a.name+' из любимых исполнителей');remove.onclick=()=>{state.favoriteArtists=state.favoriteArtists.filter(x=>x!==a);save();renderFavoriteArtists();};tile.append(b,remove);root.append(tile);}const add=document.createElement('button');add.className='favorite-add';add.textContent='＋ Добавить исполнителя';add.onclick=()=>tasteEditor.open('artists');root.append(add);}
