let pendingTasteRefresh=false;
const waveRefresh=new WaveRefresh();let waveLoading;
function refillWave(reset=false){if(loadingWave&&!reset)return waveLoading;const token=waveRefresh.begin();if(reset)home=[];waveLoading=refillWaveNow(reset,token);return waveLoading;}
async function refillWaveNow(reset,token){
 syncHistory();loadingWave=true;$('moreWave').disabled=true;$('moreWave').textContent='Подбираем музыку…';const day=dateKey(),round=waveRound++,jobs=mixRequests(positiveSeeds(state.likes,state.signals),state.genres,round,day,state.favoriteArtists,state.listening,state.signals),requestedTaste=tasteKey(state.genres,state.favoriteArtists),valid=()=>waveRefresh.current(token)&&requestedTaste===tasteKey(state.genres,state.favoriteArtists);let received=0;const errors=[];
 if(discoveryBalance(state.profile.discoveryBalance)>.65){const genre=state.genres[round%state.genres.length]||jobs.find(job=>job.discovery)?.value||'new music';jobs.splice(1,0,{mode:'search',value:genre,offset:30*(1+round%5),discovery:true});}
 const candidates=[];
 const accept=tracks=>{if(!valid())return;candidates.push(...tracks);home=buildMix([...familiarCandidates(state.likes,state.history,state.exposure,round),...candidates],state.history,tasteLikes(),state.genres,day+':'+round,100,Date.now(),state.listening,state.exposure,state.dislikes);home=waveRank(home,[],30);discoveryUI?.render(home);list('homeTracks',home.slice(0,reset?12:30),true);if(waveMode&&!reset){queue=[...queue.slice(0,index+1),...uniqueRecordings([...queue.slice(index+1),...home],queue.slice(0,index+1))];rerankFuture();}};
 try{for(let i=0;i<jobs.length;i+=2){if(!valid())break;await Promise.allSettled(jobs.slice(i,i+2).map(async job=>{try{const tracks=await provider.api(job.mode,job.value,job.offset);received+=tracks.length;accept(tracks.slice(0,30).map(t=>({...t,discovery:Boolean(job.discovery),relatedTaste:Boolean(job.relatedTaste)})));}catch(e){errors.push(e);}}));}
 if(!valid())return [];waveOffset=waveRound*30;try{localStorage.setItem('daily-mix-v7',JSON.stringify({day,round:waveRound,tracks:home,taste:requestedTaste}));}catch{}
 for(const t of home)state.exposure[identity(t).key]=Date.now();state.exposure=Object.fromEntries(Object.entries(state.exposure).sort((a,b)=>b[1]-a[1]).slice(0,1500));save();if(!received&&!home.length){$('homeTracks').textContent=errors.some(e=>e.status===401)?'Войди в аккаунт, чтобы слушать подборку.':'Пока нет новых подходящих треков. Попробуй обновить позже.';}return home;
 }finally{if(waveRefresh.current(token)){loadingWave=false;$('moreWave').disabled=false;$('moreWave').textContent='Ещё в подборку';if(pendingTasteRefresh){pendingTasteRefresh=false;refillWave(true);}}}
}
