function renderFx(){for(const k of ['speed','pitch','reverb'])$(k).value=state.effects[k];$('speedValue').textContent=Number(state.effects.speed).toFixed(2)+'×';$('pitchValue').textContent=(state.effects.pitch>0?'+':'')+Number(state.effects.pitch).toFixed(1)+' полутонов';$('reverbValue').textContent=Math.round(state.effects.reverb*100)+'%';$('lock').checked=state.lock;$('linkedRate').checked=state.linked!==false;}
function applyFx(){if(current&&!state.lock)state.trackEffects[current.id]={...state.effects};engine.setEffects(state.effects);renderFx();saveLocalSoon();}
function renderVolume(){queueMicrotask(()=>document.dispatchEvent(new Event('veyww:volume')));const value=Math.max(0,Math.min(1,Number(state.volume)||0));state.volume=value;$('volume').value=value;$('volumeFx').value=value;$('volumeValue').textContent=Math.round(value*100)+'%';$('fullVolume').value=value;$('fullVolumeValue').textContent=Math.round(value*100)+'%';$('mute').textContent=value===0?'◖×':'◖))';$('mute').setAttribute('aria-label',value===0?'Включить звук':'Выключить звук');}
function setVolume(value){state.volume=Math.max(0,Math.min(1,value));if(state.volume>0)state.lastVolume=state.volume;engine.setVolume(state.volume);renderVolume();saveLocalSoon();}
$('volume').oninput=$('volumeFx').oninput=$('fullVolume').oninput=e=>setVolume(Number(e.target.value));$('mute').onclick=()=>setVolume(state.volume>0?0:(state.lastVolume||1));
for(const k of ['speed','pitch','reverb'])$(k).oninput=()=>{state.effects=changeEffect(state.effects,k,Number($(k).value));applyFx();};
$('linkedRate').onchange=e=>{state.linked=e.target.checked;state.effects=normalizeEffects({...state.effects,linked:state.linked});applyFx();};
$('lock').onchange=e=>{state.lock=e.target.checked;engine.setEffects({...state.effects,lock:state.lock});if(current&&!state.lock)state.trackEffects[current.id]={...state.effects};save();};
$('resetFx').onclick=()=>{state.linked=true;state.effects=defaults();applyFx();};$('fxBtn').onclick=$('fxTop').onclick=()=>{$('fxDialog').showModal();};$('closeFx').onclick=()=>$('fxDialog').close();
