function previewTransfer(p){if(!p.tracks?.length)throw Error('В списке нет треков. Проверь файл или текст.');transferDraft=p;$('transferPreview').hidden=false;$('transferName').value=p.name||'Мой плейлист';$('transferCount').textContent=p.tracks.length+' названий'+(p.total!=null?' из '+p.total:'');$('transferWarning').textContent=p.warning||'Переносим названия. Для треков без аудио выбери подходящую версию в поиске при первом запуске.';$('transferTracks').replaceChildren();for(const t of p.tracks.slice(0,50)){const row=document.createElement('p');row.textContent=(t.artist?t.artist+' — ':'')+t.title;$('transferTracks').append(row);}if(p.tracks.length>50){const n=document.createElement('p');n.textContent='…и ещё '+(p.tracks.length-50);$('transferTracks').append(n);}}
