async function shareRequest(route,data){const r=await fetch('/account/'+route,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},credentials:'same-origin',body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(20000)});const j=await r.json();if(!r.ok)throw Error(j.error||'Не удалось открыть плейлист');return j;}
async function transferByLink(value){let u;try{u=new URL(value);}catch{throw Error('Вставь полную HTTPS-ссылку на плейлист');}if(u.origin===location.origin&&u.pathname==='/'&&u.searchParams.has('playlist')){const token=u.searchParams.get('playlist');if(!/^[a-f0-9]{48}$/.test(token))throw Error('Неверная ссылка veyww');return (await shareRequest('shared/'+token)).playlist;}return provider.api('import_playlist',value);}
