$('fullDislike').onclick=async()=>{if(!current)return;const track={...current},wasLiked=liked(track),key=identity(track).key,exists=state.dislikes.some(t=>identity(t).key===key);if(exists){state.dislikes=state.dislikes.filter(t=>identity(t).key!==key);window.Android?.feedback?.(JSON.stringify(state.dislikes));save();updateNow();toast('Отметка отменена');return;}feedback(track,'dislike');state.dislikes=unique([...state.dislikes,track]).slice(-600);state.likes=state.likes.filter(t=>identity(t).key!==key);window.Android?.feedback?.(JSON.stringify(state.dislikes));home=home.filter(t=>identity(t).key!==key);queue=queue.filter((t,i)=>i<=index||identity(t).key!==key);save();renderLikes();list('homeTracks',home.slice(0,30),true);updateNow();toast('Трек исключён из рекомендаций',()=>{state.dislikes=state.dislikes.filter(t=>identity(t).key!==key);state.signals=state.signals.filter(e=>!(e.action==='dislike'&&identity(e.track).key===key));if(wasLiked&&!state.likes.some(t=>t.id===track.id))state.likes.push(track);save();renderLikes();updateNow();});if(index+1<queue.length||waveMode)await next();else{if($('toggle').textContent==='Ⅱ')engine.toggle();}};

