let audioMatchGeneration=0,audioMatchDraft=null;
const playlistFingerprint=p=>JSON.stringify(p.tracks.map(t=>[t.id,t.page||'',t.url||'',t.title,t.artist,t.addedAt||0]));
function cancelAudioMatch(){audioMatchGeneration++;audioMatchDraft=null;if($('matchImportDialog').open)$('matchImportDialog').close();}
$('cancelMatchImport').onclick=$('closeMatchImport').onclick=cancelAudioMatch;
$('matchImportDialog').addEventListener('cancel',()=>{audioMatchGeneration++;audioMatchDraft=null;});
async function retryCatalog(action){for(let attempt=0;;attempt++)try{return await action();}catch(e){if(attempt>=1||e.status===401||!(/429|502|503/.test(String(e.status))||/вовремя|занят|соединен|fetch|network/i.test(e.message||'')))throw e;await new Promise(r=>setTimeout(r,400*(attempt+1)));}}
function recoveryList(root,items,select){
 root.replaceChildren();let shown=0;
 function more(){const end=Math.min(shown+100,items.length);for(;shown<end;shown++){const item=items[shown],b=document.createElement('button');b.className='import-recovery-track';b.textContent=[item.track.artist,item.track.title].filter(Boolean).join(' — ')+(item.status==='error'?' · не проверен (ошибка сети)':'');b.setAttribute('aria-label','Найти '+importQuery(item.track));b.onclick=()=>select(item);root.append(b);}if(shown<items.length){const next=document.createElement('button');next.textContent='Показать ещё ('+(items.length-shown)+')';next.onclick=()=>{next.remove();more();};root.append(next);}}
 more();
}
function searchImportedTrack(track,context){
 pendingMatch={id:track.id,...context};$('matchCaption').textContent='Подбери версию: '+[track.artist,track.title].filter(Boolean).join(' — ')+'. Нажми «Выбрать», чтобы сохранить её.';$('matchBanner').hidden=false;
 searchKind='tracks';$('searchTracks').classList.add('selected');$('searchArtists').classList.remove('selected');
 if($('matchImportDialog').open)$('matchImportDialog').close();view('search');$('query').value=importQuery(track);$('searchForm').requestSubmit();
}
function renderUnmatchedPlaylist(){
 const root=$('playlistUnmatched');root.replaceChildren();if(!selectedPlaylist)return;
 const items=selectedPlaylist.tracks.filter(t=>!t.page&&!t.url).map(track=>({track,status:'missing'}));if(!items.length)return;
 const title=document.createElement('h3');title.textContent='Нужно подобрать ('+items.length+')';const hint=document.createElement('p');hint.className='muted';hint.textContent='Треки сохранены. Нажми название — откроется поиск; выбери нужную версию.';
 const list=document.createElement('div');root.append(title,hint,list);const playlistId=selectedPlaylist.id;recoveryList(list,items,item=>searchImportedTrack(item.track,{playlistId}));
}
function chooseImportedVersion(track){
 if(!pendingMatch)return;const choice=pendingMatch;let original;
 if(choice.draftGeneration!==undefined){const draft=audioMatchDraft;if(!draft||choice.draftGeneration!==audioMatchGeneration||activeAccount!==draft.account)return;
  original=draft.original.tracks[choice.trackIndex];draft.results[choice.trackIndex]={status:'matched',track:{...track,originUrl:original.originUrl||'',addedAt:original.addedAt||0}};
  renderMatchResult(draft);$('matchImportDialog').showModal();
 }else{const playlist=state.playlists.find(p=>p.id===choice.playlistId);if(!playlist)return;const at=playlist.tracks.findIndex(t=>t.id===choice.id);if(at<0)return;original=playlist.tracks[at];playlist.tracks[at]={...track,originUrl:original.originUrl||'',addedAt:original.addedAt||Date.now()};selectedPlaylist=playlist;save();renderPlaylists();}
 pendingMatch=null;$('matchBanner').hidden=true;renderSearch();toast('Версия сохранена');
}
function renderMatchResult(draft){
 const found=draft.results.filter(r=>r?.status==='matched').length,missing=draft.results.filter(r=>r?.status==='missing').length,errors=draft.results.filter(r=>r?.status==='error').length;
 $('matchImportTitle').textContent='Результат подбора';$('matchImportStatus').textContent='С аудио: '+found+' · нужно подобрать: '+missing+' · ошибка проверки: '+errors;
 $('matchImportSummary').textContent='Сохраним весь список в исходном порядке. Ненайденные останутся отдельно в плейлисте: нажми название и выбери версию в поиске.'+(errors?' Не проверенные из-за сети можно повторить отдельно.':'');
 $('retryMatchImport').hidden=!errors;$('retryMatchImport').textContent='Повторить только ошибки ('+errors+')';$('commitMatchImport').disabled=false;$('commitMatchImport').textContent=draft.targetId?'Сохранить результат':'Сохранить плейлист';
 recoveryList($('matchImportMissing'),draft.results.map((r,index)=>({...r,index})).filter(r=>r.status!=='matched'),item=>searchImportedTrack(item.track,{draftGeneration:audioMatchGeneration,trackIndex:item.index}));
}
async function beginAudioMatch(playlist,targetId,previousDraft=null){
 const generation=++audioMatchGeneration,account=activeAccount,original=previousDraft?.original||{...playlist,tracks:playlist.tracks.map(t=>({...t}))};
 const draft=audioMatchDraft={original,targetId,account,fingerprint:previousDraft?.fingerprint||playlistFingerprint(original),results:[],session:previousDraft?.session||createMatchSession({search:q=>retryCatalog(()=>provider.search(q)),resolve:t=>retryCatalog(()=>provider.stream(t))})};
 $('matchImportTitle').textContent='Подбираем доступные записи';$('matchImportStatus').textContent='Ищем совпадения и проверяем аудио…';$('matchImportSummary').textContent='Плейлист пока не изменён.';$('matchImportMissing').replaceChildren();$('matchImportProgress').max=original.tracks.length||1;$('matchImportProgress').value=previousDraft?.results.filter(r=>r.status!=='error').length||0;
 $('commitMatchImport').disabled=true;$('retryMatchImport').hidden=true;if(!$('matchImportDialog').open)$('matchImportDialog').showModal();
 draft.results=await matchPlaylist(original.tracks,{session:draft.session,previous:previousDraft?.results||[],cancelled:()=>generation!==audioMatchGeneration,onProgress:({done,total})=>{if(generation!==audioMatchGeneration)return;$('matchImportProgress').value=done;$('matchImportStatus').textContent='Проверено '+done+' из '+total;}});
 if(generation!==audioMatchGeneration)return;renderMatchResult(draft);
}
$('matchPlaylist').onclick=()=>{if(selectedPlaylist)beginAudioMatch(selectedPlaylist,selectedPlaylist.id);};
$('retryMatchImport').onclick=()=>{if(audioMatchDraft)beginAudioMatch(audioMatchDraft.original,audioMatchDraft.targetId,audioMatchDraft);};
$('commitMatchImport').onclick=()=>{
 const draft=audioMatchDraft;if(!draft||!draft.results.length||activeAccount!==draft.account)return;
 const tracks=draft.results.map((r,i)=>r.status==='matched'?r.track:{...draft.original.tracks[i],url:'',page:''});let playlist;
 if(draft.targetId){playlist=state.playlists.find(p=>p.id===draft.targetId);if(!playlist||playlistFingerprint(playlist)!==draft.fingerprint){$('matchImportSummary').textContent='Плейлист изменился на другом устройстве. Запусти подбор ещё раз.';$('commitMatchImport').disabled=true;return;}playlist.tracks=tracks;}
 else{playlist={id:newId(),name:draft.original.name,tracks:tracks.map(t=>({...t,addedAt:Date.now()}))};state.playlists.push(playlist);clearTransfer();}
 selectedPlaylist=playlist;save();cancelAudioMatch();view('playlists');toast('Плейлист сохранён целиком: '+playlist.tracks.length+' треков');
};

