function restoreResume(resume){if(resume.playback){state.playback={...resume.playback};renderPlaybackModes();}current=resume.track;queue=resume.queue?.length?[...resume.queue]:[current];index=queue.findIndex(t=>t.id===current.id);if(index<0){queue.unshift(current);index=0;}waveMode=Boolean(resume.wave);playbackOrigin=resume.origin||'';if(resume.effects){state.effects=normalizeEffects(resume.effects);state.linked=resume.linked!==false;state.lock=Boolean(resume.locked);state.trackEffects[current.id]=state.effects;renderFx();}updateNow();renderFullPlayback({position:resume.position,duration:current.duration,playing:false});$('seek').max=current.duration||1;$('seek').value=resume.position||0;}
if(state.resume?.track?.id)restoreResume(state.resume);

for(const id of ['seek','fullSeek']){const range=$(id);range.addEventListener('pointerdown',()=>seekDragging.add(id));for(const event of ['pointerup','change','pointercancel','lostpointercapture'])range.addEventListener(event,()=>seekDragging.delete(id));}

async function startSimilar(track){if(!track?.page)return;engine.unlock();toast('Собираем подборку по треку…');try{const tracks=await provider.related(track.page);const ranked=waveRank(tracks.map(t=>({...t,relatedTaste:true}))).filter(t=>identity(t).key!==identity(track).key);if(!ranked.length){toast('Пока нет подходящих записей для этого трека');return;}await start(ranked,0,true,'По треку · '+track.title);}catch{toast('Не удалось получить похожие треки. Попробуй ещё раз.');}}
function blockArtist(track){if(!track)return;const artist=identity(track).artist;if(!artist){toast('Не удалось определить исполнителя');return;}const old=[...(state.profile.blockedArtists||[])];state.profile.blockedArtists=[...new Set([...old,artist])].slice(-100);home=home.filter(t=>!artistBlocked(t,[artist]));queue=[...queue.slice(0,index+1),...queue.slice(index+1).filter(t=>!artistBlocked(t,[artist]))];save();discoveryUI?.render(home);list('homeTracks',home.slice(0,30),true);toast('Исполнитель исключён из твоей частоты',()=>{state.profile.blockedArtists=(state.profile.blockedArtists||[]).filter(a=>a!==artist);save();});if(waveMode)next();}

