function setPlaybackHint(text,recordStall=false){let hint=document.getElementById('playbackHint');if(!hint){hint=document.createElement('span');hint.id='playbackHint';hint.className='buffering-label';hint.setAttribute('role','status');document.querySelector('.player').append(hint);}if(hint.textContent!==text){if(recordStall)qualityEvent('stall',{});hint.textContent=text;}hint.hidden=!text;}

